import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using Quickselect.
    This algorithm has an average time complexity of O(n).
    """

    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left, right, k_smallest):
        if left == right:
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(left, pivot_index - 1, k_smallest)
        else:
            return quickselect(pivot_index + 1, right, k_smallest)

    return quickselect(0, len(nums) - 1, k - 1)

import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Median of Medians algorithm.
    This algorithm has a worst-case time complexity of O(n).
    """

    def median_of_medians(left, right):
        if right - left < 5:
            return sorted(nums[left:right + 1])[len(nums[left:right + 1]) // 2]

        for i in range(left, right + 1, 5):
            sub_right = min(i + 4, right)
            median = sorted(nums[i:sub_right + 1])[len(nums[i:sub_right + 1]) // 2]
            nums[left + (i - left) // 5] = median

        mid = (right - left) // 10 + left + (right - left) % 10 // 2
        return median_of_medians(left, left + (right - left) // 5)

    def partition(left, right, pivot):
        pivot_value = nums[pivot]
        nums[pivot], nums[right] = nums[right], nums[pivot]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    size = len(nums)
    if k < 1 or k > size:
        raise ValueError("k is out of bounds")

    median_index = median_of_medians(0, size - 1)
    pivot_index = nums.index(median_index)
    pivot_index = partition(0, size - 1, pivot_index)

    if pivot_index == k - 1:
        return nums[pivot_index]
    elif pivot_index < k - 1:
        return kth_largest(nums[pivot_index + 1:], k - pivot_index - 1)
    else:
        return kth_largest(nums[:pivot_index], k)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using a modified
    binary search approach. This algorithm has an average time complexity of O(n).
    """

    def count_greater_than_mid(mid):
        count = 0
        for num in nums:
            if num > mid:
                count += 1
        return count

    left, right = min(nums), max(nums)

    while left < right:
        mid = (left + right) // 2
        if count_greater_than_mid(mid) >= k:
            left = mid + 1
        else:
            right = mid

    return left if count_greater_than_mid(left) >= k else left - 1
